type MenuButtonProps = {
  children: ReactNode;
  label: string;
  onPress?: () => void;
};

function MenuButton({ children, label, onPress }: MenuButtonProps) {
  return (
    <Pressable
      accessibilityLabel={label}
      accessibilityRole="button"
      onPress={onPress}
      style={({ pressed }) => [
        styles.button,
        pressed && onPress ? styles.pressed : undefined,
      ]}
    >
      {children}
    </Pressable>
  );
}

